import{_ as r,o as e,c as t,a2 as i}from"./chunks/framework.BWuWLRhz.js";const u=JSON.parse('{"title":"一般設定","description":"","frontmatter":{},"headers":[],"relativePath":"ja-JP/user-guide/settings/general.md","filePath":"ja-JP/user-guide/settings/general.md","lastUpdated":1787586465000}'),a={name:"ja-JP/user-guide/settings/general.md"};function n(s,o,l,d,g,c){return e(),t("div",null,[...o[0]||(o[0]=[i('<h1 id="一般設定" tabindex="-1">一般設定 <a class="header-anchor" href="#一般設定" aria-label="Permalink to &quot;一般設定&quot;">​</a></h1><p>一般設定では、システムの基本的な動作、検索ウィンドウの表示サイズやレイアウト、結果タイプの優先順位、プレビューの実行順序などを設定します。画面上部には <strong>システム</strong>、<strong>クイック検索ウィンドウ</strong>、<strong>メイン検索ウィンドウ</strong>、<strong>プレビューウィンドウ</strong>、<strong>クイックナビゲーション</strong>、<strong>プレビューとサムネイル</strong> の 6 つのタブが用意されています。</p><h2 id="_1-システム-system" tabindex="-1">1. システム（System） <a class="header-anchor" href="#_1-システム-system" aria-label="Permalink to &quot;1. システム（System）&quot;">​</a></h2><ul><li><strong>Windows 起動時に Lertaro を自動起動</strong>：ログイン時に自動で Lertaro を起動します。</li><li><strong>起動時に自動で更新を確認</strong>：アプリ起動時に最新バージョンの有無を自動確認します。</li><li><strong>サイレント自動更新</strong>：「更新を確認」が有効な場合のみ利用可能。新バージョンをバックグラウンドでダウンロードし、通知なしで自動適用します。</li><li><strong>ハードウェアアクセラレーションを有効化</strong>：既定で有効。ノート PC のデュアル GPU（NVIDIA Advanced Optimus 等）で Lertaro の常駐によりグラフィックスの自動切り替えが妨げられる場合、無効にしてソフトウェア描画に切り替えます。変更の適用には再起動が必要です。</li><li><strong>トレイアイコンを隠す</strong>：タスクバーの通知領域からアイコンを非表示にします。クイック検索バー内のロゴをクリックすればトレイメニューを開けるため、設定や終了へのアクセスが失われることはありません。</li><li><strong>Everything 互換サービス (IPC) を有効化</strong>：バックグラウンドで標準の Everything Win32 IPC プロトコルをエミュレートします。Directory Opus や Total Commander 等が Lertaro のインメモリインデックスを直接利用できるようになります。</li><li><strong>あいまい一致を有効化</strong>：既定で有効。文字飛びによる柔軟な一致を許可します。無効にすると連続した部分一致のみがヒットします（詳細は <a href="./../search-syntax.html"><strong>検索構文</strong></a> を参照）。再起動不要で即座に反映されます。</li><li><strong>クエリトークン区切り文字</strong>：1 文字の入力欄（既定は <code>:</code>）。末尾の属性トークン（例: <code>:.pdf</code>、<code>:@doc</code>、<code>:[S]</code>）のプレフィックス記号を指定します。</li><li><strong>ログレベル</strong>：「エラー / 警告 / 情報 (既定) / デバッグ」から選択し、プロセスごとのログ出力の粒度を制御します。</li><li><strong>UI 言語</strong>：アプリ全体の表示言語を切り替えます。</li></ul><h2 id="_2-クイック検索ウィンドウ-quick-search-window" tabindex="-1">2. クイック検索ウィンドウ（Quick Search Window） <a class="header-anchor" href="#_2-クイック検索ウィンドウ-quick-search-window" aria-label="Permalink to &quot;2. クイック検索ウィンドウ（Quick Search Window）&quot;">​</a></h2><p>中央にポップアップするクイック検索バーのサイズや表示順序を調整します。</p><h3 id="検索バーのレイアウト" tabindex="-1">検索バーのレイアウト <a class="header-anchor" href="#検索バーのレイアウト" aria-label="Permalink to &quot;検索バーのレイアウト&quot;">​</a></h3><ul><li><strong>検索バーの幅 (ピクセル)</strong>：設定範囲 <code>300–1200px</code>、既定値 <code>570px</code>。</li><li><strong>検索バーの高さ (ピクセル)</strong>：設定範囲 <code>45–120px</code>、既定値 <code>60px</code>。この数値に連動して結果行のアイコンサイズ、行の高さ、フォントサイズが均等に拡大縮小されます。</li><li><strong>検索ボックス内に時計を表示</strong>：検索語が空のときに、プレースホルダー文字を現在の日付・曜日・時刻に置き換えます。文字を入力すると時計は自動で消えます。</li><li><strong>ホットキーの再押下でメインウィンドウを開く</strong>：クイックウィンドウが開いている状態で再度ホットキーを押すと、入力中の検索語を維持したままメインウィンドウへ切り替えます。</li><li><strong>位置をロック</strong>：ドラッグによる位置変更を禁止し、誤操作によるズレを防ぎます。</li><li><strong>レイアウト設定をリセット</strong>：すべてのサイズとレイアウトを既定値に戻します。</li></ul><h3 id="結果タイプの優先度とトリガー文字" tabindex="-1">結果タイプの優先度とトリガー文字 <a class="header-anchor" href="#結果タイプの優先度とトリガー文字" aria-label="Permalink to &quot;結果タイプの優先度とトリガー文字&quot;">​</a></h3><ul><li><strong>優先度並び替え一覧</strong>：左側のハンドルをドラッグして、アプリ、設定、ファイル、プラグイン項目などの表示優先順位を変更します。上位のタイプが検索結果で優先的に表示されます。</li><li><strong>個別トリガー文字</strong>：特定のタイプに専用の 1 文字プレフィックス（例: ファイルフィルターに <code>;</code>）を割り当て、先頭に入力することでそのタイプのみに絞り込めます。</li></ul><h2 id="_3-メイン検索ウィンドウ-full-search-window" tabindex="-1">3. メイン検索ウィンドウ（Full Search Window） <a class="header-anchor" href="#_3-メイン検索ウィンドウ-full-search-window" aria-label="Permalink to &quot;3. メイン検索ウィンドウ（Full Search Window）&quot;">​</a></h2><p>大画面のメイン検索ウィンドウ（<code>Ctrl+F</code>）のサイズやテーブル表示を設定します。</p><ul><li><strong>ウィンドウの幅 / 高さ (ピクセル)</strong>：幅 <code>640–2000px</code>（既定 <code>854px</code>）、高さ <code>400–1400px</code>（既定 <code>480px</code>）。</li><li><strong>メインウィンドウを 1 つに制限</strong>：有効にすると、再度メインウィンドウを開いた際に新規作成せず既存のウィンドウをアクティブ化します。</li><li><strong>検索ウィンドウ設定をリセット</strong>：既定のサイズに戻します。</li><li><strong>結果テーブルの列順序</strong>：一覧ビューにおける各列（名前、パス、更新日時など）の表示順序をドラッグで並び替えます。</li><li><strong>サイドバーフィルターの順序</strong>：左側のカテゴリフィルターの並び順を変更します。各カテゴリには該当するアイテム数がリアルタイムに表示されます。</li><li><strong>アクションメニューのグループ順序</strong>：<code>Ctrl+O</code> で開くアクションメニュー内のグループ順序を変更します。</li></ul><h2 id="_4-プレビューウィンドウ-preview-window" tabindex="-1">4. プレビューウィンドウ（Preview Window） <a class="header-anchor" href="#_4-プレビューウィンドウ-preview-window" aria-label="Permalink to &quot;4. プレビューウィンドウ（Preview Window）&quot;">​</a></h2><ul><li><strong>プレビューウィンドウの幅 / 高さ (ピクセル)</strong>：幅 <code>250–900px</code>、高さ <code>250–1200px</code>。</li><li><strong>プレビュー設定をリセット</strong>：QuickLook プレビューウィンドウのサイズを標準の縦横比に戻します（画面外へのはみ出しは自動で防がれます）。</li></ul><h2 id="_5-クイックナビゲーション-quick-navigation" tabindex="-1">5. クイックナビゲーション（Quick Navigation） <a class="header-anchor" href="#_5-クイックナビゲーション-quick-navigation" aria-label="Permalink to &quot;5. クイックナビゲーション（Quick Navigation）&quot;">​</a></h2><ul><li><strong>プロバイダー順序</strong>：マウス操作による階層メニューのルートカテゴリ（お気に入り、履歴、開いているフォルダー、ファイラーのブックマーク等）の並び順を変更します。</li></ul><h2 id="_6-プレビューとサムネイル-previews-thumbnails" tabindex="-1">6. プレビューとサムネイル（Previews &amp; Thumbnails） <a class="header-anchor" href="#_6-プレビューとサムネイル-previews-thumbnails" aria-label="Permalink to &quot;6. プレビューとサムネイル（Previews &amp; Thumbnails）&quot;">​</a></h2><ul><li><strong>ファイルプレビュープロバイダーの順序</strong>：複数のプレビュー機能（内蔵デコーダーやサードパーティ製 QuickLook）の呼び出し優先順位を変更します。</li><li><strong>サムネイルプロバイダーの順序</strong>：アイコンやサムネイルを抽出するコンポーネントの優先順位を変更します。</li></ul>',19)])])}const p=r(a,[["render",n]]);export{u as __pageData,p as default};
